CREATE DATABASE IF NOT EXISTS smartclinic;
USE smartclinic;
CREATE TABLE IF NOT EXISTS admins(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) UNIQUE,email VARCHAR(255) UNIQUE,password VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS doctors(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE,password VARCHAR(255) NOT NULL,specialty VARCHAR(100));
CREATE TABLE IF NOT EXISTS patients(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(20));
CREATE TABLE IF NOT EXISTS appointments(id BIGINT AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT NOT NULL,patient_id BIGINT NOT NULL,appointment_time DATETIME NOT NULL,status VARCHAR(30),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE IF NOT EXISTS doctor_availability(id BIGINT AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT NOT NULL,available_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,FOREIGN KEY(doctor_id) REFERENCES doctors(id));